// Recipes persist with the project; source replacement does not replace motion keys.
(async()=>{const {defaultLayerRecipe}=await import('./gesture-layers.js?v=motion-v70');
for(const [key,src]of Object.entries({rigBackground:'assets/rig-room-clean-v41.png',rigUnderpaint:'assets/rig-underpaint-v41.png'})){sources[key]=src;const im=new Image();im.onload=()=>{base._renderKey='';frame(base,t)};sprites[key]=im;im.src=src}function ensureLayerSources(){for(const layer of (fx.layerRecipe||defaultLayerRecipe).layers)for(const key of [layer.source,layer.textureSource]){if(!key||key==='original'||sprites[key])continue;const im=new Image();im.onload=()=>{base._renderKey='';frame(base,t)};sprites[key]=im;sources[key]??=''}}ensureLayerSources();restoreAssets();
fx.windowPortalScale??=.38;fx.windowPortalX??=440;fx.windowPortalY??=165;
for(const key of Object.keys(directorGroups))if(/^gesturePin/.test(key)||key==='gestureRigidity')delete directorGroups[key];directorGroups.womanGesture.fields=directorGroups.womanGesture.fields.filter(field=>!['gestureGridX','gestureGridY'].includes(field[0]));
const previous=renderDepotControls;renderDepotControls=function(){previous();const host=document.querySelector('#depotControls');if(!host)return;const section=document.createElement('details');section.className='directorSection';section.innerHTML='<summary>Reusable layer animation · advanced</summary><p class="sub">Replace a source without changing its motion. Masks and contact anchors must be retargeted to the new artwork. Remove any layer independently. Coordinates use the 960 × 540 stage.</p>';host.append(section);
const recipe=fx.layerRecipe||structuredClone(defaultLayerRecipe),select=document.createElement('select');select.setAttribute('aria-label','Animation layer');for(const layer of recipe.layers)select.add(new Option(layer.id,layer.id));section.append(select);const fields=document.createElement('div');section.append(fields);
function show(){fields.replaceChildren();const layer=recipe.layers.find(l=>l.id===select.value);if(!layer)return;const save=()=>{fx.layerRecipe=recipe;ensureLayerSources();assetSave();base._renderKey='';frame(base,t)};
for(const [key,label,type]of [['enabled','Visible','checkbox'],['id','Layer name','text'],['source','Source slot','text'],['type','Content type · image or text','text'],['text','Text content','text'],['textureEnabled','Fill text with an image','checkbox'],['textureSpeed','Fill drift','number'],['textureScale','Fill scale','number'],['textureOpacity','Fill amount','number'],['font','Text font','text'],['color','Text color','text'],['x','Offset X','number'],['y','Offset Y','number'],['scale','Scale','number'],['rotation','Rotation degrees','number'],['opacity','Opacity','number'],['z','Layer order','number']]){const labelEl=document.createElement('label');labelEl.textContent=label;const el=document.createElement('input');el.type=type;if(type==='checkbox')el.checked=key==='enabled'?layer.enabled!==false:!!layer[key];else el.value=layer[key]??({scale:1,opacity:1,type:'image'}[key]??'');el.onchange=()=>{layer[key]=type==='checkbox'?el.checked:type==='number'?Number(el.value):el.value;save()};labelEl.append(el);fields.append(labelEl)}
for(const [key,label]of [['mask','Mask polygon'],['anchors','Contact anchors'],['keys','Motion keys · time, x, y, scale, rotation, opacity']]){const l=document.createElement('label');l.textContent=label;const input=document.createElement('textarea');input.value=JSON.stringify(layer[key]||[]);input.onchange=()=>{try{const value=JSON.parse(input.value);if(!Array.isArray(value))throw Error('Use an array');layer[key]=value;input.setCustomValidity('');save()}catch(e){input.setCustomValidity(e.message);input.reportValidity()}};l.append(input);fields.append(l)}
toolButton(fields,'Replace layer image…',()=>{const slot=layer.source==='original'||!layer.source?'customLayer_'+layer.id:layer.source;layer.source=slot;save();chooseAsset(slot)});toolButton(fields,'Replace text fill image…',()=>{layer.textureSource||='layerTexture_'+layer.id;layer.textureEnabled=true;save();chooseAsset(layer.textureSource)});toolButton(fields,'Remove layer',()=>{recipe.layers=recipe.layers.filter(l=>l!==layer);save();renderDepotControls()});}
select.onchange=show;show();toolButton(section,'Add image or text layer',()=>{recipe.layers.push({id:'Layer '+(recipe.layers.length+1),source:'customLayer'+Date.now(),type:'image',keys:[]});fx.layerRecipe=recipe;assetSave();renderDepotControls()});
const json=document.createElement('textarea');json.setAttribute('aria-label','Complete layer recipe JSON');json.value=JSON.stringify(recipe,null,2);section.append(json);toolButton(section,'Apply recipe JSON',()=>{try{const value=JSON.parse(json.value);if(!Array.isArray(value.layers)||value.layers.some(l=>!l.id))throw Error('Each layer needs an id');fx.layerRecipe=value;ensureLayerSources();restoreAssets();assetSave();renderDepotControls()}catch(e){json.setCustomValidity(e.message);json.reportValidity()}});toolButton(section,'Restore artwork preset',()=>{delete fx.layerRecipe;assetSave();renderDepotControls()});
const portal=document.createElement('details');portal.innerHTML='<summary>Window content mapping</summary>';section.append(portal);toolNumbers(portal,fx,[['windowPortalX','Content center X',0,960,1],['windowPortalY','Content center Y',0,540,1],['windowPortalScale','Content scale',.1,1,.01]]);
};renderDepotControls();window.motionLayersReady=true;window.dispatchEvent(new Event('motion-layers-ready'));})();
